def _note_model(context, session, model) -> None:
    """Keep the model (glm-4.6, gpt-5.5, ...) next to the session's turn and decisions."""
    if not session or not model:
        return
    agent_repo.note_model(context.conn, str(session), str(model))
    context.conn.commit()

