      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body),
    })
    return await r.json()
  } catch {
    return {} // Solo License is down: Amp behaves as if it were not installed
  }
}

export default function (amp: PluginAPI) {
  amp.on("agent.start", async (event: any) => {
    await gate("agent.start", { thread_id: event.thread?.id, prompt: event.message, cwd: process.cwd() })
    return {}
  })
  amp.on("tool.call", async (event: any) => {
    const d = await gate("tool.call", { thread_id: event.thread?.id, tool_name: event.tool, tool_input: event.input, cwd: process.cwd() })
    if (d?.action === "reject-and-continue") return { action: "reject-and-continue", message: d.message ?? "Blocked by Solo License" }
    return { action: "allow" }
  })
  amp.on("tool.result", async (event: any) => {
    await gate("tool.result", { thread_id: event.thread?.id, tool_name: event.tool, tool_input: event.input, status: event.status, error: event.error, cwd: process.cwd() })
  })
  amp.on("agent.end", async (event: any) => {
    const d = await gate("agent.end", { thread_id: event.thread?.id, status: event.status, cwd: process.cwd() })
    if (d?.action === "continue" && d.userMessage) return { action: "continue", userMessage: d.userMessage }
  })
}
"""


def _amp(repo: Path, url: str) -> Path:
    path = repo / ".amp" / "plugins" / "solo-license.ts"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(AMP_PLUGIN.replace("__URL__", json.dumps(validate_url(url))), encoding="utf-8")
    return path


KILO_PLUGIN = """// solo-license: earned autonomy for Kilo Code (any model: GLM, Claude, ...)
import type { Plugin } from "@kilocode/plugin"

const BASE: string = process.env.SOLO_LICENSE_URL ?? __URL__

async function gate(event: string, body: unknown): Promise<any> {
  try {
    const r = await fetch(`${BASE}/api/hooks/kilo/${event}`, {
      method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body),
    })
    return await r.json()
  } catch {
    return {} // Solo License is down: Kilo's own permission rules decide
  }
}

const models: Record<string, unknown> = {}

const SoloLicense: Plugin = async ({ directory }) => ({
  "chat.message": async (input: any) => {
    if (input?.sessionID && input?.model) models[input.sessionID] = input.model
  },
  "tool.execute.before": async (input: any, output: any) => {
    const d = await gate("tool.execute.before", { tool_name: input.tool, tool_input: output.args, sessionID: input.sessionID, model: models[input.sessionID], cwd: directory })
    if (d?.decision === "deny") throw new Error(d.reason ?? "Blocked by Solo License")
  },
  "tool.execute.after": async (input: any, output: any) => {
    await gate("tool.execute.after", { tool_name: input.tool, tool_input: output?.args ?? {}, sessionID: input.sessionID, model: models[input.sessionID], cwd: directory, result: output?.metadata })
  },
  event: async ({ event }: any) => {
    if (event?.type === "session.idle") await gate("session.idle", { sessionID: event.properties?.sessionID, cwd: directory })
  },
})

export default { id: "solo-license", server: SoloLicense }
"""


def _kilo(repo: Path, url: str) -> Path:
    path = repo / ".kilo" / "plugin" / "solo-license.ts"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(KILO_PLUGIN.replace("__URL__", json.dumps(validate_url(url))), encoding="utf-8")
    return path


def _auggie(repo: Path, url: str) -> Path:
    """Auggie runs only .sh / .cmd / .ps1 / .bat files, so each event gets a tiny script."""
    folder = repo / ".solo-license" / "auggie"
    folder.mkdir(parents=True, exist_ok=True)
    python, hook = _paths(repo)
    windows = os.name == "nt"

    def script(event: str) -> str:
        if windows:
            target = folder / f"{event}.cmd"
            target.write_text(f'@echo off\r\nrem {MARK}\r\n"{python}" "{hook}" auggie {event}\r\n'
                              "exit /b %ERRORLEVEL%\r\n", encoding="utf-8")
        else:
            target = folder / f"{event}.sh"
            target.write_text(f"#!/bin/sh\n# {MARK}\nexec {shlex.quote(python)} {shlex.quote(hook)} auggie {event}\n",
                              encoding="utf-8")
            target.chmod(target.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
        return _safe_path(str(target), "repository")

    def entry(event: str, timeout: int = 30000, matcher: bool = True) -> dict:
        return {**({"matcher": ".*"} if matcher else {}),
                "hooks": [{"type": "command", "command": script(event), "timeout": timeout}],
                "metadata": {"includeUserContext": True}}

    ours = {"PreToolUse": [entry("PreToolUse")], "PostToolUse": [entry("PostToolUse")],
            "Stop": [entry("Stop", 150000, matcher=False)]}
    path = repo / ".augment" / "settings.local.json"
    data = _load(path)
    data["hooks"] = _merge(data.get("hooks", {}), ours)
    _save(path, data)
    return path


def _goose(repo: Path, url: str) -> Path:
    plugin = repo / ".agents" / "plugins" / MARK
    _save(plugin / "plugin.json", {"name": MARK, "version": "0.1.0",
                                   "description": "Solo License: earned autonomy for coding agents"})
    cmd = lambda e, t=30: {"type": "command", "command": _command(repo, "goose", e), "timeout": t}  # noqa: E731
    path = plugin / "hooks" / "hooks.json"
    _save(path, {"hooks": {e: [{"hooks": [cmd(e, 150 if e == "Stop" else 30)]}]
                           for e in ("UserPromptSubmit", "PreToolUse", "PostToolUse", "PostToolUseFailure", "Stop")}})
    return path


def _junie(repo: Path, url: str) -> Path:
    cmd = lambda e, t=30: {"type": "command", "command": _command(repo, "junie", e), "timeout": t}  # noqa: E731
    ours = {
        "UserPromptSubmit": [{"hooks": [cmd("UserPromptSubmit", 10)]}],
        "PreToolUse": [{"hooks": [cmd("PreToolUse")]}],
        "Stop": [{"hooks": [cmd("Stop", 150)]}],
    }
    path = Path.home() / ".junie" / "config.json"
    data = _load(path)
    data["hooks"] = _merge(data.get("hooks", {}), ours)
    _save(path, data)
    return path


def _zcode(repo: Path, url: str) -> Path:
    python, hook = _paths(repo)

    def run(event: str, timeout: int = 30000) -> dict:
        return {"type": "process", "command": python, "args": [hook, "zcode", event], "timeoutMs": timeout}

    ours = {
        "UserPromptSubmit": [{"hooks": [run("UserPromptSubmit")]}],
        "PreToolUse": [{"hooks": [run("PreToolUse")]}],
        "PermissionRequest": [{"hooks": [run("PermissionRequest")]}],
        "PostToolUse": [{"hooks": [run("PostToolUse")]}],
        "PostToolUseFailure": [{"hooks": [run("PostToolUseFailure")]}],
        "Stop": [{"hooks": [run("Stop", 150000)]}],
    }
    path = Path.home() / ".zcode" / "cli" / "config.json"
    data = _load(path)
    hooks = data.setdefault("hooks", {})
    hooks["enabled"] = True
    hooks["events"] = _merge(hooks.get("events", {}), ours)
    _save(path, data)
    return path


WRITERS.update({
    "qwen": _qwen, "droid": _droid, "kimi": _kimi, "crush": _crush, "amp": _amp, "kilo": _kilo,
    "auggie": _auggie, "goose": _goose, "junie": _junie, "zcode": _zcode,
})


def _more_probes(repo: Path, home: Path) -> dict[str, list[Path]]:
    kimi = Path(os.environ["KIMI_CODE_HOME"]) if os.environ.get("KIMI_CODE_HOME") else home / ".kimi-code"
    return {
        "qwen": [repo / ".qwen", home / ".qwen"],
        "droid": [repo / ".factory", home / ".factory"],
        "kimi": [kimi],
        "crush": [repo / "crush.json", repo / ".crush.json", home / ".config" / "crush",
                  home / "AppData" / "Local" / "crush"],
        "amp": [repo / ".amp", home / ".config" / "amp"],
        "kilo": [repo / ".kilo", repo / ".kilocode", home / ".config" / "kilo"],
        "auggie": [repo / ".augment", home / ".augment"],
        "goose": [repo / ".agents" / "plugins", home / ".config" / "goose"],
        "junie": [home / ".junie"],
        "zcode": [home / ".zcode"],
    }

